Algorithm Waves
  Dimension t[14] As Integer;
  For i <- 0 To 13 Do
    Read t[i];
  EndFor
  Define streak As Integer <- 0;
  Define waves As Integer <- 0;
  Define longest As Integer <- 0;
  For Each temperature In t Do
    If temperature > 30 Then
      streak <- streak + 1;
    Else
      If streak >= 3 Then
        waves <- waves + 1;
        If streak > longest Then
          longest <- streak;
        EndIf
      EndIf
      streak <- 0;
    EndIf
  EndFor
  Write "Waves: ", waves;
  Write "Longest: ", longest;
EndAlgorithm

